        bool returned;
        try c.transfer(from, caddress, tos, v) returns (bool ok) {
            reverted = false;
            returned = ok;
        } catch {
            reverted = true;
        }

        bool expectedRevert = (tos.length == 0);
        bool allCallsOk = true;
        if (tos.length > 0) {
            (bool s0, ) = caddress.staticcall(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, tos[0], v[0]));
            allCallsOk = s0;
        }
        if (!expectedRevert && allCallsOk) {
            expectedRevert = false;
        } else if (!expectedRevert) {
            expectedRevert = true;
        }

        assert(reverted == expectedRevert);
    }

    receive() external payable {}
}

